//! Identifier casing helpers.
//!
//! All of these walk the input one byte at a time. ASCII letters are the only
//! bytes ever case-folded, so multi-byte UTF-8 sequences survive unchanged and
//! the result is always valid UTF-8.

/// Rebuilds a `String` from bytes that only ever went through ASCII-only
/// transformations of valid UTF-8, so validity is guaranteed.
fn from_ascii_safe(bytes: Vec<u8>) -> String {
    String::from_utf8(bytes).expect("ASCII-only transforms preserve UTF-8 validity")
}

/// Uppercases the ASCII letters in `word`, leaving every other byte alone.
pub fn upcase(word: &str) -> String {
    from_ascii_safe(word.bytes().map(|b| b.to_ascii_uppercase()).collect())
}

/// Lowercases the ASCII letters in `word`, leaving every other byte alone.
pub fn downcase(word: &str) -> String {
    from_ascii_safe(word.bytes().map(|b| b.to_ascii_lowercase()).collect())
}

/// `snake_cases` an identifier: every uppercase letter past the first byte is
/// prefixed with `_`, then the whole string is lowercased.
///
/// `"XMLParser"` becomes `"x_m_l_parser"` and `"hello_WORLD"` becomes
/// `"hello__w_o_r_l_d"` — the underscore is inserted regardless of what
/// precedes the uppercase letter.
pub fn underscore(word: &str) -> String {
    let mut out = Vec::with_capacity(word.len());
    for (i, byte) in word.bytes().enumerate() {
        if byte.is_ascii_uppercase() {
            if i > 0 {
                out.push(b'_');
            }
            out.push(byte.to_ascii_lowercase());
        } else {
            out.push(byte);
        }
    }
    from_ascii_safe(out)
}

/// `camelCases` an identifier: underscores are dropped and the byte following
/// a run of underscores is uppercased.
///
/// The leading byte is never touched, so `"hello_world"` becomes
/// `"helloWorld"` while `"Hello_world"` becomes `"HelloWorld"`.
pub fn camelize(word: &str) -> String {
    let mut out = Vec::with_capacity(word.len());
    let mut capitalize_next = false;
    for byte in word.bytes() {
        if byte == b'_' {
            capitalize_next = true;
        } else if capitalize_next {
            out.push(byte.to_ascii_uppercase());
            capitalize_next = false;
        } else {
            out.push(byte);
        }
    }
    from_ascii_safe(out)
}

/// Replaces every underscore with a dash, leaving case untouched.
pub fn dasherize(word: &str) -> String {
    from_ascii_safe(
        word.bytes()
            .map(|b| if b == b'_' { b'-' } else { b })
            .collect(),
    )
}

/// Turns an identifier into prose: underscores become spaces and the very
/// first byte is uppercased.
///
/// Only the leading byte is considered, so `"_foo"` humanizes to `" foo"` and
/// no `_id` suffix is stripped: `"employee_id"` becomes `"Employee id"`.
pub fn humanize(word: &str) -> String {
    let mut out: Vec<u8> = word
        .bytes()
        .map(|b| if b == b'_' { b' ' } else { b })
        .collect();
    if let Some(first) = out.first_mut() {
        *first = first.to_ascii_uppercase();
    }
    from_ascii_safe(out)
}

/// Uppercases the first byte of `word`, used to build `classify`'s output.
pub fn capitalize_first(word: &str) -> String {
    let mut out: Vec<u8> = word.bytes().collect();
    if let Some(first) = out.first_mut() {
        *first = first.to_ascii_uppercase();
    }
    from_ascii_safe(out)
}

