//! The uncountable word list and the ordered singularization rule table.
//!
//! The C++ library drives `singularize` with a list of regular expressions
//! that are tried in order; the first one to match wins. Each rule below is a
//! hand-rolled equivalent of one of those patterns, documented with the
//! pattern and replacement it stands for. Because every pattern is anchored at
//! the end of the word (`$`), matching reduces to a suffix test plus a check on
//! the text immediately preceding the suffix.
//!
//! The patterns are case sensitive: `"Boxes"` singularizes to `"Box"` (the
//! lowercase `xes` still matches) but `"BOXES"` is left alone entirely.

/// Words that are their own plural and singular form.
///
/// The comparison is an exact, case-sensitive match against the whole input,
/// so `"Fish"` and `"big fish"` are *not* uncountable.
pub const UNCOUNTABLE: [&str; 10] = [
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

/// True when `word` is in the uncountable list.
pub fn is_uncountable(word: &str) -> bool {
    UNCOUNTABLE.contains(&word)
}

/// A single singularization rule: `Some(result)` when the pattern matched.
type Rule = fn(&str) -> Option<String>;

/// The rule table, in the order the C++ library tries it. The generic
/// `s$` rule sits last so the specific rules get first refusal.
const SINGULAR_RULES: [Rule; 17] = [
    quizzes,
    matrices,
    vert_ind_ices,
    oxen,
    alias_status_es,
    octop_vir_i,
    cris_ax_test_es,
    o_es,
    bus_es,
    m_l_ice,
    x_ch_ss_sh_es,
    ies,
    ves,
    ses,
    ti_a,
    news,
    trailing_s,
];

/// `(quiz)zes$` -> `\1`
fn quizzes(word: &str) -> Option<String> {
    let stem = word.strip_suffix("zes")?;
    stem.ends_with("quiz").then(|| stem.to_string())
}

/// `(matr)ices$` -> `\1ix`
fn matrices(word: &str) -> Option<String> {
    let stem = word.strip_suffix("ices")?;
    stem.ends_with("matr").then(|| format!("{stem}ix"))
}

/// `(vert|ind)ices$` -> `\1ex`
fn vert_ind_ices(word: &str) -> Option<String> {
    let stem = word.strip_suffix("ices")?;
    (stem.ends_with("vert") || stem.ends_with("ind")).then(|| format!("{stem}ex"))
}

/// `^(ox)en$` -> `\1`
///
/// Anchored at both ends, so only the exact word `"oxen"` matches: `"oxens"`
/// falls through to `s$` and `"boxen"` is left alone.
fn oxen(word: &str) -> Option<String> {
    (word == "oxen").then(|| "ox".to_string())
}

/// `(alias|status)es$` -> `\1`
fn alias_status_es(word: &str) -> Option<String> {
    let stem = word.strip_suffix("es")?;
    (stem.ends_with("alias") || stem.ends_with("status")).then(|| stem.to_string())
}

/// `(octop|vir)i$` -> `\1us`
fn octop_vir_i(word: &str) -> Option<String> {
    let stem = word.strip_suffix('i')?;
    (stem.ends_with("octop") || stem.ends_with("vir")).then(|| format!("{stem}us"))
}

/// `(cris|ax|test)es$` -> `\1is`
///
/// Tried before `(x|ch|ss|sh)es$`, which is why `"taxes"` singularizes to
/// `"taxis"` rather than `"tax"`.
fn cris_ax_test_es(word: &str) -> Option<String> {
    let stem = word.strip_suffix("es")?;
    (stem.ends_with("cris") || stem.ends_with("ax") || stem.ends_with("test"))
        .then(|| format!("{stem}is"))
}

/// `(o)es$` -> `\1`
fn o_es(word: &str) -> Option<String> {
    let stem = word.strip_suffix("es")?;
    stem.ends_with('o').then(|| stem.to_string())
}

/// `(bus)es$` -> `\1`
fn bus_es(word: &str) -> Option<String> {
    let stem = word.strip_suffix("es")?;
    stem.ends_with("bus").then(|| stem.to_string())
}

/// `([m|l])ice$` -> `\1ouse`
///
/// The original writes this as a character class, so the `|` inside it is a
/// literal alternative alongside `m` and `l`. It is unanchored, hence
/// `"slice"` -> `"slouse"`.
fn m_l_ice(word: &str) -> Option<String> {
    let stem = word.strip_suffix("ice")?;
    matches!(stem.as_bytes().last(), Some(b'm' | b'|' | b'l')).then(|| format!("{stem}ouse"))
}

/// `(x|ch|ss|sh)es$` -> `\1`
fn x_ch_ss_sh_es(word: &str) -> Option<String> {
    let stem = word.strip_suffix("es")?;
    (stem.ends_with('x')
        || stem.ends_with("ch")
        || stem.ends_with("ss")
        || stem.ends_with("sh"))
    .then(|| stem.to_string())
}

/// `([^aeiouy]|qu)ies$` -> `\1y`
///
/// Both branches keep the matched text and append `y`, so the result is always
/// the stem plus `y`; only whether the rule fires differs.
fn ies(word: &str) -> Option<String> {
    let stem = word.strip_suffix("ies")?;
    let last = *stem.as_bytes().last()?;
    let consonant = !matches!(last, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');
    (consonant || stem.ends_with("qu")).then(|| format!("{stem}y"))
}

/// `([^f])ves$` -> `\1fe`
///
/// This is reached before any `f`-producing variant, so `"wolves"` becomes
/// `"wolfe"` and `"hives"` becomes `"hife"`.
fn ves(word: &str) -> Option<String> {
    let stem = word.strip_suffix("ves")?;
    let last = *stem.as_bytes().last()?;
    (last != b'f').then(|| format!("{stem}fe"))
}

/// `((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$` -> `\1\2sis`
///
/// Only the `(a)naly` branch fills capture group 2, and the replacement splices
/// that group back in — so `"analyses"` yields `"analyasis"` while every other
/// branch (group 2 empty) behaves normally, e.g. `"bases"` -> `"basis"`.
/// The pattern is unanchored on the left, which is how `"databases"` reaches
/// the `(b)a` branch and becomes `"databasis"`.
fn ses(word: &str) -> Option<String> {
    const BRANCHES: [(&str, &str); 7] = [
        ("analy", "a"),
        ("ba", ""),
        ("diagno", ""),
        ("parenthe", ""),
        ("progno", ""),
        ("synop", ""),
        ("the", ""),
    ];
    let stem = word.strip_suffix("ses")?;
    BRANCHES
        .iter()
        .find(|(branch, _)| stem.ends_with(branch))
        .map(|(_, group2)| format!("{stem}{group2}sis"))
}

/// `([ti])a$` -> `\1um`
fn ti_a(word: &str) -> Option<String> {
    let stem = word.strip_suffix('a')?;
    matches!(stem.as_bytes().last(), Some(b't' | b'i')).then(|| format!("{stem}um"))
}

/// `(n)ews$` -> `\1ews`
///
/// A no-op replacement whose only job is to stop `s$` from firing, keeping
/// `"news"` intact. It is case sensitive, so `"News"` still becomes `"New"`.
fn news(word: &str) -> Option<String> {
    word.ends_with("news").then(|| word.to_string())
}

/// `s$` -> `` — the catch-all: drop a single trailing `s`.
fn trailing_s(word: &str) -> Option<String> {
    word.strip_suffix('s').map(str::to_string)
}

/// Applies the rule table to `word`, returning the first match or `word`
/// unchanged when nothing applies.
pub fn apply_singular_rules(word: &str) -> String {
    SINGULAR_RULES
        .iter()
        .find_map(|rule| rule(word))
        .unwrap_or_else(|| word.to_string())
}

