use crate::inflection::casing;
use crate::inflection::rules;

/// Namespace for the inflection entry points. All methods are associated
/// functions, mirroring `inflection::Inflector` in the C++ library.
pub struct Inflector;

impl Inflector {
    /// Prepares the inflection tables.
    ///
    /// The rule table is a compile-time constant here, so there is nothing to
    /// build at runtime; the method exists to keep the C++ call sequence intact.
    pub fn initialize() {}

    /// Pluralizes `word` by appending `s`, unless it is empty or uncountable.
    ///
    /// The rule set is deliberately this blunt: `"box"` pluralizes to `"boxs"`
    /// and `"child"` to `"childs"`.
    pub fn pluralize(word: &str) -> String {
        if word.is_empty() || rules::is_uncountable(word) {
            return word.to_string();
        }
        format!("{word}s")
    }

    /// Singularizes `word` using the ordered rule table in [`rules`].
    pub fn singularize(word: &str) -> String {
        if word.is_empty() || rules::is_uncountable(word) {
            return word.to_string();
        }
        rules::apply_singular_rules(word)
    }

    /// `camelCases` `word`, leaving the leading byte as-is.
    pub fn camelize(word: &str) -> String {
        casing::camelize(word)
    }

    /// `snake_cases` `word`.
    pub fn underscore(word: &str) -> String {
        casing::underscore(word)
    }

    /// Turns a table name into a class name: singularize, camelize, then
    /// uppercase the first byte.
    pub fn classify(word: &str) -> String {
        casing::capitalize_first(&casing::camelize(&Self::singularize(word)))
    }

    /// Turns a class name into a table name: underscore, then pluralize.
    pub fn tableize(word: &str) -> String {
        Self::pluralize(&casing::underscore(word))
    }

    /// Turns `word` into prose: underscores to spaces, first byte uppercased.
    pub fn humanize(word: &str) -> String {
        casing::humanize(word)
    }

    /// Replaces underscores with dashes.
    pub fn dasherize(word: &str) -> String {
        casing::dasherize(word)
    }

    /// Uppercases the ASCII letters in `word`.
    pub fn upcase(word: &str) -> String {
        casing::upcase(word)
    }

    /// Lowercases the ASCII letters in `word`.
    pub fn downcase(word: &str) -> String {
        casing::downcase(word)
    }
}

