//! Entry point mirroring `tests/test12.cpp`: 12 inflection calls spread across
//! the first four command line arguments.
//!
//! The library modules are pulled in by path so this file builds either way:
//!   rustc test12.rs            (standalone, produces ./test12)
//!   cargo build --release      (as the `test12` binary of this package)
#[path = "src/inflection/mod.rs"]
mod inflection;

use crate::inflection::Inflector;

fn main() {
    Inflector::initialize();

    // 12 API calls, using different arguments.
    // Only the first four arguments are looked at.
    let args: Vec<String> = std::env::args().collect();
    for i in 1..args.len().min(5) {
        let word = &args[i];

        match i {
            1 => {
                println!("{}", Inflector::pluralize(word));
                println!("{}", Inflector::singularize(word));
            }
            2 => {
                println!("{}", Inflector::camelize(word));
                println!("{}", Inflector::underscore(word));
            }
            3 => {
                println!("{}", Inflector::classify(word));
                println!("{}", Inflector::tableize(word));
            }
            4 => {
                println!("{}", Inflector::humanize(word));
                println!("{}", Inflector::dasherize(word));
                println!("{}", Inflector::upcase(word));
                println!("{}", Inflector::downcase(word));
            }
            _ => {}
        }
    }
}

