//! Word inflection: pluralization, singularization and identifier casing.
//!
//! Every transformation here is byte-oriented and ASCII-only, matching the
//! `<cctype>` based implementation of the C++ original: bytes outside the
//! `A-Z` / `a-z` ranges (including UTF-8 continuation bytes) are passed
//! through untouched rather than being case-folded.

pub mod casing;
pub mod inflector;
pub mod rules;

pub use inflector::Inflector;

