#[cfg(test)]
mod tests {
    use super::Inflector;

    #[test]
    fn documented_examples() {
        assert_eq!(Inflector::pluralize("cat"), "cats");
        assert_eq!(Inflector::singularize("cat"), "cat");
        assert_eq!(Inflector::camelize("hello_world"), "helloWorld");
        assert_eq!(Inflector::underscore("hello_world"), "hello_world");
        assert_eq!(Inflector::classify("user_account"), "UserAccount");
        assert_eq!(Inflector::tableize("user_account"), "user_accounts");
        assert_eq!(Inflector::humanize("employee_id"), "Employee id");
        assert_eq!(Inflector::dasherize("employee_id"), "employee-id");
        assert_eq!(Inflector::upcase("employee_id"), "EMPLOYEE_ID");
        assert_eq!(Inflector::downcase("EMPLOYEE_ID"), "employee_id");
        assert_eq!(Inflector::underscore("XMLParser"), "x_m_l_parser");
        assert_eq!(Inflector::camelize("XMLParser"), "XMLParser");
        assert_eq!(Inflector::tableize("person"), "persons");
    }

    #[test]
    fn pluralize_only_appends_s_or_keeps_uncountables() {
        for (input, expected) in [
            ("box", "boxs"),
            ("child", "childs"),
            ("baby", "babys"),
            ("bus", "buss"),
            ("", ""),
            ("fish", "fish"),
            ("series", "series"),
            ("police", "police"),
            ("Fish", "Fishs"),      // uncountables are case sensitive
            ("big fish", "big fishs"), // and matched against the whole input
        ] {
            assert_eq!(Inflector::pluralize(input), expected, "pluralize({input:?})");
        }
    }

    #[test]
    fn singularize_rule_table() {
        for (input, expected) in [
            ("quizzes", "quiz"),
            ("matrices", "matrix"),
            ("vertices", "vertex"),
            ("indices", "index"),
            ("oxen", "ox"),
            ("oxens", "oxen"), // ^(ox)en$ is fully anchored
            ("boxen", "boxen"),
            ("aliases", "alias"),
            ("statuses", "status"),
            ("octopi", "octopus"),
            ("viri", "virus"),
            ("taxi", "taxi"),
            ("crises", "crisis"),
            ("axes", "axis"),
            ("taxes", "taxis"), // (cris|ax|test)es$ wins over (x|ch|ss|sh)es$
            ("boxes", "box"),
            ("shoes", "sho"),
            ("buses", "bus"),
            ("mice", "mouse"),
            ("slice", "slouse"), // ([m|l])ice$ is unanchored
            ("x|ice", "x|ouse"), // and the `|` is a literal class member
            ("churches", "church"),
            ("glasses", "glass"),
            ("babies", "baby"),
            ("movies", "movy"),
            ("soliloquies", "soliloquy"),
            ("wolves", "wolfe"),
            ("lives", "life"),
            ("hives", "hife"),
            ("ves", "ve"),
            ("bases", "basis"),
            ("theses", "thesis"),
            ("databases", "databasis"),
            ("analyses", "analyasis"), // the `\1\2sis` capture-group quirk
            ("canalyses", "canalyasis"),
            ("data", "datum"),
            ("media", "medium"),
            ("news", "news"),
            ("cats", "cat"),
            ("boss", "bos"),
            ("", ""),
        ] {
            assert_eq!(Inflector::singularize(input), expected, "singularize({input:?})");
        }
    }

    #[test]
    fn rules_are_case_sensitive() {
        assert_eq!(Inflector::singularize("News"), "New");
        assert_eq!(Inflector::singularize("NEWS"), "NEWS");
        assert_eq!(Inflector::singularize("Boxes"), "Box");
        assert_eq!(Inflector::singularize("BOXES"), "BOXES");
        assert_eq!(Inflector::singularize("Mice"), "Mice");
        assert_eq!(Inflector::singularize("Jeans"), "Jean");
    }

    #[test]
    fn casing_edge_cases() {
        assert_eq!(Inflector::camelize("_foo"), "Foo");
        assert_eq!(Inflector::camelize("foo__bar"), "fooBar");
        assert_eq!(Inflector::camelize("foo_"), "foo");
        assert_eq!(Inflector::camelize("__"), "");
        assert_eq!(Inflector::underscore("Foo::Bar"), "foo::_bar");
        assert_eq!(Inflector::underscore("hello_WORLD"), "hello__w_o_r_l_d");
        assert_eq!(Inflector::underscore("1Abc"), "1_abc");
        assert_eq!(Inflector::humanize("_foo"), " foo");
        assert_eq!(Inflector::humanize("foo__bar"), "Foo  bar");
        assert_eq!(Inflector::humanize("123_abc"), "123 abc");
        assert_eq!(Inflector::dasherize("foo__bar"), "foo--bar");
        assert_eq!(Inflector::classify("schema.table_names"), "Schema.tableName");
        assert_eq!(Inflector::classify("mice"), "Mouse");
        assert_eq!(Inflector::tableize("Foo::Bar"), "foo::_bars");
    }

    #[test]
    fn non_ascii_bytes_pass_through_untouched() {
        assert_eq!(Inflector::upcase("café"), "CAFé");
        assert_eq!(Inflector::downcase("Grüße"), "grüße");
        assert_eq!(Inflector::underscore("naïve_TEST"), "naïve__t_e_s_t");
        assert_eq!(Inflector::upcase("ÄÖÜ"), "ÄÖÜ");
        assert_eq!(Inflector::humanize("ÄÖÜ"), "ÄÖÜ");
    }
}
